import type { CSSProperties, ReactNode } from "react";

import { cn } from "../lib/utils";
import { BarSizeProvider } from "./barSize";

/**
 * Bar — a horizontal strip with three slots (left · center · right).
 * Structure is unchanged from the reset: no appearance cascade, no
 * tone/state, just the three slots. What changed in the shadcn/Tailwind
 * migration is HOW it's painted — Tailwind utilities against the shadcn CSS
 * variables in src/globals.css instead of raw `style={{...}}` colors,
 * borrowing the visual vocabulary (not the props) of
 * packages/bbox-ui/src/bar.tsx.
 *
 * WHY the grid template is COMPUTED, not a fixed `1fr auto 1fr` (Zach: "if
 * the center slot is empty or so, then things in the other slots should
 * just continue to expand width wise, and not truncate. Unless you
 * specifically set a width limit"): `1fr auto 1fr` forces the left/right
 * tracks to stay EQUAL width even when one of them (or center) is empty —
 * that symmetry is exactly what real centering needs, but it also means an
 * empty center/right still claims (and wastes) half the bar's width, and a
 * long `left` label truncates against that artificial half-width ceiling
 * with the other half sitting empty. Measured live: a previous lane's own
 * `AllSizes` cascade cluster had already been moved from `left` to `center`
 * and its swatch widened 420→520px specifically to dodge this — a symptom
 * fix, not a cause fix, and reverted below now that the cause is fixed.
 * `barGridTemplateColumns` (below) keeps `1fr auto 1fr`'s symmetric flanks
 * ONLY when `center` actually holds content (centering is structurally
 * impossible without equal flanks, filled or not); otherwise the unused
 * slot's track collapses to `0` and `left`'s own track becomes the single
 * `1fr` that absorbs everything center/right aren't using — so it only
 * truncates once the BAR ITSELF is out of room, never before. A caller that
 * wants a truncation limit narrower than "however wide the bar naturally
 * is" sets one explicitly by wrapping its own content in a `width`-bounded
 * box — see `Bar.stories.tsx`'s `Widths` gallery — rather than `Bar`
 * growing a new prop for it.
 *
 * WHY no `rounded-lg`/`border`/`bg-card` here: a Bar is a layout strip, not
 * a card — the same way `Flex` paints nothing of its own. Zach: "I don't
 * like how the bars have these borders. they should fill the block footer
 * and headers edge to edge... the only lines are the dividers." A Bar
 * filling `Block`'s header/footer must read as flush with it, not as a
 * pill floating inside it — `Block`'s own `border-b`/`border-t` supply the
 * only lines. A standalone Bar story that wants to show the strip's own
 * extent adds a wrapper (e.g. a dashed box) at the STORY level instead.
 *
 * WHY `size` is also published via `BarSizeProvider`: Zach's size-cascade
 * ask — a Bar's contents should size themselves off the Bar's own `size`
 * rather than each getting hand-tuned. See `barSize.tsx` for the mapping
 * from these four rungs onto each consumer's own scale.
 */
function barGridTemplateColumns(hasCenter: boolean, hasRight: boolean): string {
  if (hasCenter) return "1fr auto 1fr";
  if (hasRight) return "1fr 0 auto";
  return "1fr 0 0";
}

export const BAR_SIZES = ["sm", "md", "lg", "xl"] as const;
export type BarSize = (typeof BAR_SIZES)[number];

/** Bar height per rung, px. */
export const BAR_HEIGHT: Record<BarSize, number> = { sm: 28, md: 36, lg: 48, xl: 60 };

export interface BarProps {
  left?: ReactNode;
  center?: ReactNode;
  right?: ReactNode;
  size?: BarSize;
  style?: CSSProperties;
}

// WHY `overflow-clip` + a 4px `overflow-clip-margin` instead of plain
// `overflow-hidden`: a focusable control flush against a cell's edge (a
// left-slot FoldingChevron, a right-slot Toggle/Button) paints its
// focus-visible ring OUTSIDE its own border box — `hidden` clips that ink
// the instant it crosses the cell boundary, which is the actual cause of
// the bug Zach reported ("chevron has a box cut off on its left") and,
// measured live, hits any focusable control sitting flush at a cell edge,
// not just the chevron. `overflow-clip-margin` is the CSS-spec-native fix:
// it only relaxes where PAINT (ink like a box-shadow ring or an outline) is
// allowed to bleed past the clip box, layout overflow — the thing this
// class exists to contain, e.g. EditableText's own `minWidth:0`/ellipsis
// truncation still clips flush at (edge + 4px). 4px covers both the
// shadcn ring-3 box-shadow (3px spread, 0 offset) and the browser's native
// default outline that a bare-button control like FoldingChevron falls
// back to. Only takes effect on `overflow: clip` (not `hidden`), which is
// otherwise behaviourally identical for this cell's purposes — no scroll
// either way.
const cellClass = "flex min-w-0 items-center overflow-clip [overflow-clip-margin:4px]";

export function Bar({ left, center, right, size = "md", style }: BarProps) {
  return (
    <BarSizeProvider size={size}>
      <div
        data-slot="bar"
        data-size={size}
        // WHY `group`: a plain Tailwind marker class, paints nothing on its
        // own — it exists so a `FoldingChevron reveal="hover"` inside this
        // Bar can key its `group-hover`/`group-focus-within` reveal off the
        // Bar itself ("the surrounding region... the Bar/header it lives
        // in", not the 24px button). Harmless for every Bar that has no
        // such child.
        className={cn("group grid w-full items-center gap-2 px-3 text-sm text-card-foreground")}
        style={{
          gridTemplateColumns: barGridTemplateColumns(center !== undefined, right !== undefined),
          height: BAR_HEIGHT[size],
          ...style,
        }}
      >
        <div data-slot="bar-left" className={cn(cellClass, "justify-start")}>
          {left}
        </div>
        <div data-slot="bar-center" className={cn(cellClass, "justify-center")}>
          {center}
        </div>
        <div data-slot="bar-right" className={cn(cellClass, "justify-end")}>
          {right}
        </div>
      </div>
    </BarSizeProvider>
  );
}

"use client";

import { createContext, useContext, type ReactNode } from "react";

import type { BarSize } from "./bar";
import type { EditableTextSize } from "./editableText.layout";
import type { GlyphSize } from "./glyph.layout";

/**
 * src/components/barSize.tsx — the size CASCADE from `Bar` down to its own
 * contents. Zach: "various things inside of the bar will size themselves
 * correctly... with a 'large bar' vs small bar you don't need to hand tune
 * each element inside." A React context, mirroring `glyph.tsx`'s own
 * resolver-context pattern (provider + `use*` hook), not a new prop
 * threaded through every layer in between — `Bar` already owns a `size`
 * prop (bar.tsx); this only makes that value reach descendants.
 *
 * The mapping from Bar's four rungs (sm/md/lg/xl) onto each consumer's OWN
 * size scale lives HERE, in one place, rather than scattered per component.
 * `Glyph`/`EditableText` already share Bar's exact four-rung ladder, so
 * their mapping is the identity — still spelled out below so all five
 * mappings are visible in one lookup. `Badge`/`Button`/`Toggle` each carry
 * a differently-shaped scale of their own.
 *
 * An explicit size prop on any child ALWAYS wins — every consumer only
 * calls into this context as the fallback when its own prop is
 * `undefined`, same "explicit beats derived" rule `glyphFootprint` already
 * applies to its own size/sizePreset pair.
 */

const BarSizeContext = createContext<BarSize | undefined>(undefined);

/** Mounted by `Bar` itself (bar.tsx) — not meant to be reached for by callers. */
export function BarSizeProvider({ size, children }: { size: BarSize; children?: ReactNode }) {
  return <BarSizeContext.Provider value={size}>{children}</BarSizeContext.Provider>;
}

/** `undefined` outside any `Bar` — "not inside a cascade," not an error;
 *  same shape as `useGlyphResolver`'s "no provider mounted" case. */
export function useBarSize(): BarSize | undefined {
  return useContext(BarSizeContext);
}

/** Glyph's own ladder (glyph.layout.ts's `GLYPH_SIZES`) is identical to
 *  Bar's four rungs, so the cascade is the identity. */
export const BAR_SIZE_TO_GLYPH_PRESET: Record<BarSize, GlyphSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** EditableText's own ladder (editableText.layout.ts's `EDITABLE_TEXT_SIZES`)
 *  is the same four-rung ladder too — see that file's own comment on why
 *  Glyph/EditableText/Port each keep an independent ladder rather than
 *  sharing one, even though the VALUES line up. */
export const BAR_SIZE_TO_EDITABLE_TEXT_SIZE: Record<BarSize, EditableTextSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** Badge has no size scale of its own yet (badge.tsx was a plain stock
 *  shadcn Badge, one size only) — this cascade is what gives it one,
 *  matching Bar's own four rungs directly. */
export type BadgeSize = "sm" | "md" | "lg" | "xl";
export const BAR_SIZE_TO_BADGE_SIZE: Record<BarSize, BadgeSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** Button and Toggle each already ship a THREE-rung size scale
 *  (sm/default/lg — no "xl"), so Bar's `xl` clamps down to their largest
 *  rung rather than this cascade inventing a fourth one they don't have. */
export type ButtonToggleSize = "sm" | "default" | "lg";
export const BAR_SIZE_TO_BUTTON_SIZE: Record<BarSize, ButtonToggleSize> = {
  sm: "sm",
  md: "default",
  lg: "lg",
  xl: "lg",
};
export const BAR_SIZE_TO_TOGGLE_SIZE: Record<BarSize, ButtonToggleSize> = BAR_SIZE_TO_BUTTON_SIZE;

/**
 * bbox-ui EditableText layout — the portable geometry of the text-leaf.
 *
 * EditableText's own size ladder, deliberately NOT `layout.ts`'s `TEXT_SIZES`
 * (frozen for T1) and NOT `Glyph`'s or `Port`'s own independent ladders —
 * see docs/T1-SPEC.md §0 on why three components each get their own 18px
 * "small" rung rather than one shared file. React-free, engine-free, same
 * discipline as `layout.ts`.
 *
 * PROVENANCE: OURS, AD HOC. NO PRIOR ART IS CLAIMED, and this file has no
 * donor — stated explicitly rather than left as an absence, because an
 * uncited file is ambiguous between "written here" and "nobody wrote down
 * where this came from", and only one of those is true.
 *
 * There is also no algorithm here to have prior art FOR. Every export is a
 * lookup table or a total `Record` over a string union: the size ladder, the
 * three font stacks, and the two align→flex maps. The one function with a
 * rule in it, `editableTextFontPx`, is a single ternary. The CSS values on
 * the right-hand side of those Records (`flex-start`/`center`/`flex-end`)
 * are of course the CSS Flexbox spec's, but this file does not implement
 * them — it names them and hands them to the browser, which is not a
 * citation-bearing act. The reason the tables are TOTAL Records rather than
 * ternaries is a real decision and it is documented at each seam below.
 */

/** EditableText's own ladder. Values match the board's own Text Size row. */
export const EDITABLE_TEXT_SIZES = { sm: 18, md: 24, lg: 36, xl: 44 } as const;
// WHY `EditableTextSize` widens by union rather than `EDITABLE_TEXT_SIZES` growing a
// fifth rung: "custom" has no single px value — it is the ESCAPE from the
// named ladder into `sizePx`, so it cannot live in a `Record<name, px>` the
// way sm/md/lg/xl do. `editableTextFontPx` below is the one place that resolves
// either shape back to a number. See docs/TEXTBOX-EDITING-SPEC.md §1.
export type EditableTextSize = keyof typeof EDITABLE_TEXT_SIZES | "custom";

/** The font-size in px for a given `size`/`sizePx` pair — the one function
 * that knows "custom" escapes the named ladder. `sizePx` is ignored for the
 * four named rungs, exactly like `font`/`align` ignore props that don't
 * apply to them. */
export function editableTextFontPx(size: EditableTextSize, sizePx: number): number {
  return size === "custom" ? sizePx : EDITABLE_TEXT_SIZES[size];
}

// WHY the array is the source and the type is derived: annotating the field
// table stopped the SCHEMA advertising a value the component cannot render,
// but not the reverse — widening the union and adding its stack left the
// panel silently offering three of four fonts with the suite green. With one
// runtime array behind both, a test can pin the field's options to it and
// catch growth in either direction. Same shape as BLOCK_ORIENTATIONS.
export const EDITABLE_TEXT_FONTS = ["sans", "sketch", "mono"] as const;
export type EditableTextFont = (typeof EDITABLE_TEXT_FONTS)[number];
export const EDITABLE_TEXT_FONT_STACKS: Record<EditableTextFont, string> = {
  sans: 'ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif',
  sketch: '"Segoe Print", "Bradley Hand", cursive',
  mono: 'ui-monospace, "SF Mono", Menlo, Consolas, monospace',
};

type FlexPlacement = "flex-start" | "center" | "flex-end";

// WHY total Records rather than the ternaries these replace: deriving the
// union from the array made widening it reach the panel automatically, which
// is what we wanted — but a ternary has a fall-through, so a new member
// arrived as a live segment that silently rendered `center`, typecheck clean
// and every test green. A total Record is what makes the array the real
// source: adding a member is a compile error until someone says where it
// lays out. The same shape as EDITABLE_TEXT_FONT_STACKS, which is why `font`
// already failed loudly and these two did not.
export const EDITABLE_TEXT_VERTICAL_ALIGNS = ["top", "middle", "bottom"] as const;
export type EditableTextVerticalAlign = (typeof EDITABLE_TEXT_VERTICAL_ALIGNS)[number];
export const EDITABLE_TEXT_ALIGN_ITEMS: Record<EditableTextVerticalAlign, FlexPlacement> = {
  top: "flex-start",
  middle: "center",
  bottom: "flex-end",
};
export function editableTextAlignItems(align: EditableTextVerticalAlign): FlexPlacement {
  return EDITABLE_TEXT_ALIGN_ITEMS[align];
}

export const EDITABLE_TEXT_HORIZONTAL_ALIGNS = ["left", "middle", "right"] as const;
export type EditableTextHorizontalAlign = (typeof EDITABLE_TEXT_HORIZONTAL_ALIGNS)[number];
export const EDITABLE_TEXT_JUSTIFY_CONTENT: Record<EditableTextHorizontalAlign, FlexPlacement> = {
  left: "flex-start",
  middle: "center",
  right: "flex-end",
};
export function editableTextJustifyContent(justify: EditableTextHorizontalAlign): FlexPlacement {
  return EDITABLE_TEXT_JUSTIFY_CONTENT[justify];
}

/**
 * src/components/glyph.layout.ts — ported by value from
 * packages/bbox-ui/src/glyph.layout.ts (Glyph v2, docs/GLYPH-PLAN.md's
 * contract). Same size ladder and override-vs-preset rule; this app has no
 * `layout.ts`/`TEXT_SIZES` of its own to stay independent of, but the
 * ladder is kept in its own file anyway so `glyph.tsx` matches its source
 * shape 1:1 for anyone diffing the two later.
 *
 * DONOR LINES (read 2026-09-17; the donor is 53 lines and lives in this
 * same repo, so this is a `diff` away, not an archaeology dig):
 *   • `glyph.layout.ts:11`    `GLYPH_SIZES` — same four rungs, same values.
 *   • `glyph.layout.ts:20-43` the two interfaces.
 *   • `glyph.layout.ts:45-52` `glyphFootprint`, including the `!== undefined`
 *     rule restated below. Arithmetic unchanged.
 *
 * NO PRIOR ART IS CLAIMED, and none applies: the "ladder plus override"
 * rule and the square `size + 2*padding` footprint are this repo's own
 * product decisions, not an algorithm. There is nothing here to cite but
 * the donor.
 */
export const GLYPH_SIZES = { sm: 18, md: 24, lg: 36, xl: 44 } as const;
export type GlyphSize = keyof typeof GLYPH_SIZES;
export const GLYPH_SIZE_NAMES: Record<GlyphSize, string> = {
  sm: "Small",
  md: "Medium",
  lg: "Large",
  xl: "Extra Large",
};

export interface GlyphFootprintInput {
  sizePreset?: GlyphSize;
  /** px override — when given, wins over `sizePreset`. */
  size?: number;
  padding?: number;
}

export interface GlyphFootprint {
  /** Resolved side length of the glyph itself, px. */
  size: number;
  padding: number;
  /** Outer box a host places on canvas — `size + 2*padding`, square. */
  w: number;
  h: number;
}

/**
 * The override-vs-preset size rule, in one place. `size` absent/undefined
 * is NOT the same as `size: 0` — an explicit 0 is a real override, so this
 * checks `!== undefined`, never falsy/`??`, to keep that case distinguishable.
 */
export function glyphFootprint({
  sizePreset = "sm",
  size,
  padding = 0,
}: GlyphFootprintInput): GlyphFootprint {
  const resolvedSize = size !== undefined ? size : GLYPH_SIZES[sizePreset];
  const outer = resolvedSize + 2 * padding;
  return { size: resolvedSize, padding, w: outer, h: outer };
}

// src/components/popover.tsx — based on the stock shadcn `new-york` Popover
// (apps/docs/src/registry/new-york-v4/ui/popover.tsx, over Base UI's
// `@base-ui/react/popover`), NOT copied verbatim: that stock copy only ever
// positions against its own trigger, and this kit needs a popover that can
// hang off a point on the canvas that has no DOM element at all (the
// font-size popover in docs/menus/screenshots/03-font-size-popover.png opens
// off the selection, not off a button). `PopoverPositioner.Props` already
// accepts `anchor: Element | VirtualElement | ...` (verified against
// apps/storybook-basics/node_modules/@base-ui/react/internals/
// useAnchorPositioning.d.ts) — the stock copy's `Pick` just never asked for
// it. `container` and `collisionPadding` are exposed for the same reason:
// they're the two other host-contract knobs docs/menus/MENU-KIT-DESIGN.md
// §4 names ("container? — portal target inside the host's token scope",
// "collisionPadding" for the boundary a canvas-anchored popup must respect).
"use client";

import { Popover as PopoverPrimitive } from "@base-ui/react/popover";

import { cn } from "../lib/utils";

function Popover({ ...props }: PopoverPrimitive.Root.Props) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />;
}

function PopoverTrigger({ ...props }: PopoverPrimitive.Trigger.Props) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />;
}

export interface PopoverContentProps
  extends PopoverPrimitive.Popup.Props,
    Pick<
      PopoverPrimitive.Positioner.Props,
      "align" | "alignOffset" | "side" | "sideOffset" | "anchor" | "collisionPadding"
    > {
  /** WHY: portal target inside the host's own token/theme scope (the kit's
      universal host contract, MENU-KIT-DESIGN.md §4) — `undefined` keeps
      Base UI's own default of `document.body`, which is fine for a host
      with no scoped root. */
  container?: PopoverPrimitive.Portal.Props["container"];
  /** WHY (ported concept, menuLabModel.ts's `popoverMode`): a live text
      editor open elsewhere on the surface (an inline rename field, a
      color-hex input) must keep its OWN focus while this popover is open —
      the default "move focus into the popup on open" would steal the caret
      mid-keystroke. Maps to Base UI Popup's `initialFocus`, narrowed to a
      boolean because the kit only ever needs "move focus" vs "leave it
      alone," never `initialFocus`'s ref/interaction-type callback forms.
      Default `true` (Base UI's own default); pill/editing surfaces pass
      `false`. */
  autoFocus?: boolean;
}

function PopoverContent({
  className,
  align = "center",
  alignOffset = 0,
  side = "bottom",
  sideOffset = 4,
  anchor,
  collisionPadding,
  container,
  autoFocus = true,
  ...props
}: PopoverContentProps) {
  return (
    <PopoverPrimitive.Portal container={container}>
      <PopoverPrimitive.Positioner
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
        anchor={anchor}
        collisionPadding={collisionPadding}
        className="isolate z-50 outline-none"
      >
        <PopoverPrimitive.Popup
          data-slot="popover-content"
          initialFocus={autoFocus}
          className={cn(
            "data-open:animate-in data-closed:animate-out data-closed:fade-out-0 data-open:fade-in-0 data-closed:zoom-out-95 data-open:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ring-foreground/10 bg-popover text-popover-foreground flex flex-col gap-2.5 rounded-lg p-2.5 text-sm shadow-md ring-1 duration-100 data-[side=inline-start]:slide-in-from-right-2 data-[side=inline-end]:slide-in-from-left-2 z-50 w-72 origin-(--transform-origin) outline-hidden",
            className,
          )}
          {...props}
        />
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Portal>
  );
}

export { Popover, PopoverContent, PopoverTrigger };

/* src/editor/controlGlyphs.css — the paint for controlGlyphs.tsx.
 *
 * Ported from the read-only donor at /home/bam/systemsketch:
 *   • src/appearance/appearance.css:461-511 — `.systemsketch-appearance__glyph`,
 *     its `[data-role='solid']` / `[data-role='slash']` children, and
 *     `__font`.
 *   • src/appearance/appearance.css:370-391 — `.systemsketch-appearance__swatch`
 *     and its `[data-mixed]` state.
 *
 * WHY this file exists at all, and why it did not on the first pass: the
 * glyph COMPONENT ported cleanly — `FillGlyph` genuinely draws four different
 * shapes for solid / pattern / semi / none — but its styling lived in the
 * donor's app-wide `appearance.css`, which is not a file anyone thought to
 * port along with a `.tsx`. So every glyph shipped emitting a class name that
 * nothing defined, fell back to the SVG defaults (`fill: black`, no stroke),
 * and rendered as an identical near-invisible black square on a dark panel —
 * Solid, Hatched, Transparent and No fill all indistinguishable, and twelve
 * line styles all drawn as the same sliver.
 *
 * Every story still passed, because a play function asserts roles and
 * presence and never asks what colour anything is. Nothing short of looking
 * at the rendered pixels was going to catch it, which is exactly why looking
 * is a step and not a formality.
 *
 * The `fill: none; stroke: currentcolor` default plus a `[data-role='solid']`
 * child that inverts to `fill: currentcolor; stroke: none` is the donor's own
 * contract, not an invention here: the glyph functions are WRITTEN against
 * it — `FillGlyph` draws an outlined box and then overlays a `data-role`
 * rect to mean "painted", so a stylesheet that made everything solid by
 * default would erase the very distinction the glyph exists to draw.
 *
 * Sizing differs deliberately. The donor paints at 24px because it sits in
 * tldraw's own 40px control cells; this kit's cells come from the trunk's
 * `Bar`/`Toolbar` size cascade, so the box is 1.25rem and inherits `color`
 * from whatever control owns it rather than naming a palette.
 */

.bbox-control-glyph {
  display: block;
  width: 1.25rem;
  height: 1.25rem;
  flex: 0 0 auto;
  fill: none;
  stroke: currentcolor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* "Painted", in whatever the owning control's colour currently is. Donor:
 * appearance.css:497-500. */
.bbox-control-glyph [data-role="solid"] {
  fill: currentcolor;
  stroke: none;
}

.bbox-control-glyph [data-role="slash"] {
  stroke-width: 1.5;
}

/* A stroke-width rung reads as a bar whose thickness IS the value, so it must
 * paint rather than outline — at the thin rung an outline would be two
 * hairlines with a gap, which says the opposite of "thin". */
.bbox-control-glyph [data-width] {
  fill: currentcolor;
  stroke: none;
}

/* The font family preview ("Aa"), drawn as text rather than as a path so it
 * actually renders in the family it names. Donor: appearance.css:506-513. */
.bbox-control-glyph-font {
  display: grid;
  width: 1.25rem;
  height: 1.25rem;
  place-items: center;
  font-size: 0.75rem;
  font-weight: 650;
  line-height: 1;
}

/* A colour swatch is painted by an inline `background` the component resolves,
 * so this only supplies the shape, the fallback and the inset ring that keeps
 * a white swatch visible on a white surface. Donor: appearance.css:370-377. */
.bbox-control-glyph-swatch {
  display: block;
  width: 1.25rem;
  height: 1.25rem;
  flex: 0 0 auto;
  border-radius: 50%;
  background: #757575;
  box-shadow: inset 0 0 0 1px rgb(255 255 255 / 20%);
}

/* A mixed selection has no one colour to show, so it shows a slash instead of
 * picking a winner — the same refusal-to-lie the trunk applies to truncated
 * text. Donor: appearance.css:387-391. */
.bbox-control-glyph-swatch[data-mixed] {
  background:
    linear-gradient(135deg, transparent 44%, #b9bbc0 44%, #b9bbc0 56%, transparent 56%),
    #3a3b40;
}

// src/editor/controlGlyphs.tsx — ported from SystemSketch, read-only
// donor at /home/bam/systemsketch, revision
// `10748b8ccdb374e71714f3d351abc43947ecfb0e`:
//
//   • `src/appearance/AppearanceGlyph.tsx:54-81` — `GLYPH_FAMILIES`, the
//     dispatch-table WHY (quoted below, unedited).
//   • `src/appearance/AppearanceGlyph.tsx:330-506` — every drawn glyph
//     function (`FillGlyph`, `DashGlyph`, `SizeGlyph`, `StrokeWidthGlyph`,
//     `FontGlyph`, `AlignGlyph`, `RoutingGlyph`, `ArrowheadGlyph`) and their
//     small supporting tables (`DASH_ARRAYS`, `SIZE_HEIGHTS`,
//     `GLYPH_UNITS_PER_PX`, `FONT_STACKS`, `VERTICAL_ALIGN_ROWS`) —
//     "already editor-free except swatch" (task brief), copied verbatim.
//   • `src/appearance/AppearanceGlyph.tsx:307-328` — `ColorSwatch`'s shape
//     (an `<span>` painted with a resolved hex, or a `data-mixed` empty
//     swatch when none resolves — the span itself is :321-326), reworked as
//     `swatchGlyph` below.
//
//     CORRECTED 2026-09-18: this line previously cited `:196-230`, which is
//     the `AppearanceGlyph` DISPATCH function, not `ColorSwatch` at all —
//     caught by an independent judge that followed the citation instead of
//     trusting it, and confirmed against the pinned revision above, so it
//     was wrong when written rather than drifted since. Worth naming rather
//     than quietly correcting: a citation nobody opens is indistinguishable
//     from a correct one, which is exactly why this repo's rule is that a
//     plausible reference from memory is worse than an honest "ours".
//   • `src/appearance/strokeMeta.ts:87-91` — `STROKE_WIDTH_PX` (the three
//     rung→px values `StrokeWidthGlyph` draws at) and, at `:195-199`,
//     `strokeWidthPxForRung`'s one-line lookup — inlined here as a local
//     const + helper since the donor file itself is not ported (it also
//     carries live shape-metadata read/write this kit has no shape model
//     for; only the three numbers travel).
//
// WHAT CHANGED in the port:
//
//   1. THE GLYPH TABLE BECOMES HOST-EXTENDABLE (design's second required
//      change). The donor's `GLYPH_FAMILIES` is keyed by the closed
//      `ContextualGlyphFamily` union and dispatches through `AppearanceGlyph`/
//      `TriggerGlyph`, both of which also reach for FigJam's traced icon set
//      and an Excalidraw vendored-icon layer ahead of these drawn fallbacks
//      (`AppearanceGlyph.tsx:196-320`) — real engine/app coupling (a `tldraw`
//      `Editor` parameter, `FIGJAM_ICONS`, `TLDRAW_GEO_ICONS`) that has no
//      place in a kit importing no canvas engine. What ports is the
//      DISPATCH SHAPE, not the multi-layer fallback: `GlyphFamilies` is a
//      plain `Record<string, GlyphRenderer>` (an open string key, not the
//      closed union — a host names its own families) exported as
//      `DEFAULT_GLYPH_FAMILIES`, and a host renderer merges its own by
//      spreading (`{ ...DEFAULT_GLYPH_FAMILIES, myKind: myRenderer }`) —
//      still a table, never an if-chain, so a new control that previews
//      like an existing one needs zero renderer changes, same as the donor.
//      The `geo` family is deliberately NOT ported: it dispatches on
//      `TLDRAW_GEO_ICONS`, a tldraw-vendored icon set, i.e. canvas-engine
//      data. A host wanting shape-preview glyphs supplies its own family.
//   2. `swatch` becomes an INJECTED renderer, not a table entry. The donor's
//      `ColorSwatch` reads a live theme via `editor.getCurrentTheme()` — the
//      one genuinely editor-coupled family (this file's own header says so).
//      `swatchGlyph(hexFor)` takes the resolver as a plain function and
//      returns an ordinary `GlyphRenderer`, so a host wires
//      `swatchGlyph((name) => myPalette[name])` into its own merged
//      `GlyphFamilies` under whatever key its vocabulary uses.
//   3. `ArrowheadGlyph`'s `atStart` boolean is no longer a component prop —
//      `GlyphRenderer` takes only `(value)`. The donor's registry keyed
//      START and END as two separate glyph families
//      (`arrowheadStart`/`arrowheadEnd`) precisely so each can close over its
//      own `atStart`; `DEFAULT_GLYPH_FAMILIES` keeps that same two-key split
//      rather than smuggling a second parameter into `GlyphRenderer`.
//   4. `FillGlyph`'s `data-role="solid"` `<rect>` used a fixed `opacity`
//      switch (`value === 'semi' ? 0.35 : 1`) matching a donor constant
//      (`fillPaint.TRANSPARENT_FILL_ALPHA`) this kit does not import — the
//      literal `0.35` travels as a comment-cited number, not a live import.
import type { ReactElement, ReactNode } from "react";

// The glyphs are written AGAINST this stylesheet's contract (outlined by
// default, `[data-role="solid"]` to mean painted), so importing it here rather
// than leaving it to the host is what makes the component self-contained —
// same call codeEditor.tsx:62 makes for codeEditor.css, and what lets the
// registry generator ship it without anyone declaring it by hand.
import "./controlGlyphs.css";

/** One family's preview renderer: a control's raw value in, a drawn (or
    absent) preview out. No editor, no DOM measurement, no engine types. */
export type GlyphRenderer = (value: string | undefined) => ReactNode;

/** An open, host-extendable table — see change (1) above. A host merges its
    own families in by spreading over `DEFAULT_GLYPH_FAMILIES`. */
export type GlyphFamilies = Readonly<Record<string, GlyphRenderer>>;

function Svg({ children }: { children: ReactNode }) {
  return (
    <svg viewBox="0 0 20 20" className="bbox-control-glyph" aria-hidden="true">
      {children}
    </svg>
  );
}

/** The fill treatments, drawn on the same square so they can be compared. */
function FillGlyph(value: string | undefined): ReactNode {
  const box = <rect x="3.5" y="3.5" width="13" height="13" rx="2" />;
  if (value === "none") return <Svg>{box}</Svg>;
  if (value === "pattern" || value === "lined-fill") {
    const lines =
      value === "pattern" ? ["M4 12l8-8", "M4 16l12-12", "M8 16l8-8"] : ["M4 8h12", "M4 11.5h12", "M4 15h12"];
    return (
      <Svg>
        {box}
        {lines.map((d) => (
          <path key={d} d={d} strokeWidth={1} />
        ))}
      </Svg>
    );
  }
  // The glyph says what the fill does: Solid is fully painted, Transparent is
  // a wash you can read through. 0.35 matches the donor's own
  // `fillPaint.TRANSPARENT_FILL_ALPHA` closely enough to be recognised in a
  // 16px cell (see change (4) above — the constant travels, the import doesn't).
  const opacity = value === "semi" ? 0.35 : 1;
  return (
    <Svg>
      <rect x="3.5" y="3.5" width="13" height="13" rx="2" data-role="solid" opacity={opacity} />
      {box}
    </Svg>
  );
}

/**
 * The glyph's cadence per line style. `async` is a cable's own packet
 * rhythm — a long carrier, a hair of a gap, a short packet — scaled from the
 * 56/4/10/4 the donor canvas paints
 * (`connectionPresentation.ASYNC_PACKET_DASHARRAY`) down to the 14 units this
 * glyph has to say it in.
 */
const DASH_ARRAYS: Record<string, string | undefined> = {
  draw: undefined,
  solid: undefined,
  dashed: "4 3",
  dotted: "0.1 3.2",
  async: "9 1 2 1",
  none: undefined,
};

function DashGlyph(value: string | undefined): ReactNode {
  if (value === "none") {
    return (
      <Svg>
        <path d="M3 17 17 3" data-role="slash" />
        <circle cx="10" cy="10" r="7" />
      </Svg>
    );
  }
  return (
    <Svg>
      <path
        d={value === "draw" ? "M3 12.5c4-6 6 2 14-4.5" : "M3 10h14"}
        strokeDasharray={DASH_ARRAYS[value ?? "solid"]}
        strokeLinecap={value === "dotted" ? "round" : "butt"}
        data-dash={value}
      />
    </Svg>
  );
}

/** A host draws each size at its own size; four bars do the same job compactly. */
const SIZE_HEIGHTS: Record<string, number> = { s: 3, m: 6, l: 9, xl: 13 };

function SizeGlyph(value: string | undefined): ReactNode {
  const height = SIZE_HEIGHTS[value ?? "m"] ?? 6;
  return (
    <Svg>
      <rect x="3" y={10 - height / 2} width="14" height={height} rx={height / 2} data-role="solid" />
    </Svg>
  );
}

// Ported from strokeMeta.ts:87-91 — the three rungs `StrokeWidthGlyph` draws
// at. Not re-exported: a host that needs the pixel value elsewhere owns its
// own copy, same as any other app-side stroke-width policy.
const STROKE_WIDTH_PX: Record<string, number> = { thin: 2, medium: 3.5, thick: 7 };

/** Ported from strokeMeta.ts:195-199 (`strokeWidthPxForRung`). */
function strokeWidthPxForRung(value: string | undefined): number | undefined {
  return value !== undefined && value in STROKE_WIDTH_PX ? STROKE_WIDTH_PX[value] : undefined;
}

/**
 * The thickness rung drawn at the width it actually paints.
 *
 * WHY drawn rather than a traced pair (ported, AppearanceGlyph.tsx:365-372):
 * there are three rungs and a traced icon set commonly has two, so a traced
 * pair plus one invented sibling would be exactly the mismatch a
 * truthful-rendering rule refuses. Plain rules of increasing weight serve
 * both a stacked shape row and a connector's row beside its line styles.
 *
 * The 20-unit box is painted at 24px, so a rung's scene-unit width is
 * divided by that 1.2 ratio to land on screen at the width it will draw on
 * canvas.
 */
const GLYPH_UNITS_PER_PX = 24 / 20;

function StrokeWidthGlyph(value: string | undefined): ReactNode {
  const px = strokeWidthPxForRung(value) ?? STROKE_WIDTH_PX.medium;
  const height = px / GLYPH_UNITS_PER_PX;
  return (
    <Svg>
      <rect x="3" y={10 - height / 2} width="14" height={height} rx={height / 2} data-role="solid" data-width={value} />
    </Svg>
  );
}

const FONT_STACKS: Record<string, string> = {
  sans: 'Inter, ui-sans-serif, system-ui, sans-serif',
  serif: 'Georgia, "Times New Roman", serif',
  mono: "ui-monospace, SFMono-Regular, Menlo, monospace",
  draw: '"Comic Sans MS", "Segoe Print", cursive',
};

function FontGlyph(value: string | undefined): ReactNode {
  return (
    <span className="bbox-control-glyph-font" style={{ fontFamily: FONT_STACKS[value ?? "sans"] ?? FONT_STACKS.sans }} aria-hidden="true">
      Aa
    </span>
  );
}

/** Three lines: stacked to one side for vertical, ragged to one side for horizontal. */
const VERTICAL_ALIGN_ROWS: Record<string, readonly number[]> = {
  start: [5, 8.5, 12],
  middle: [6.5, 10, 13.5],
  end: [8, 11.5, 15],
};

function AlignGlyph(value: string | undefined, vertical?: boolean): ReactNode {
  if (vertical) {
    const rows = VERTICAL_ALIGN_ROWS[value ?? "middle"] ?? VERTICAL_ALIGN_ROWS.middle;
    return (
      <Svg>
        {rows.map((y) => (
          <path key={y} d={`M4 ${y}h12`} />
        ))}
      </Svg>
    );
  }
  // The short middle line is what makes the alignment readable at 20px.
  const widths = [14, 8, 14];
  const start = (width: number) => (value === "end" ? 17 - width : value === "middle" ? 10 - width / 2 : 3);
  return (
    <Svg>
      {widths.map((width, index) => (
        <path key={index} d={`M${start(width)} ${6 + index * 4}h${width}`} />
      ))}
    </Svg>
  );
}

function RoutingGlyph(value: string | undefined): ReactNode {
  if (value === "elbow") {
    return (
      <Svg>
        <path d="M3 15h6V5h8" />
      </Svg>
    );
  }
  // `straight` is the canonical Line shape value; `line` is a stock spline
  // style's word for the same thing, kept so a raw style value still draws.
  if (value === "straight" || value === "line") {
    return (
      <Svg>
        <path d="M3 15 17 5" />
      </Svg>
    );
  }
  return (
    <Svg>
      <path d="M3 15c5 0 3-10 14-10" />
    </Svg>
  );
}

/** The line is always drawn the same way; only the cap changes. See change
    (3) above for why `atStart` is baked in per-family rather than a second
    `GlyphRenderer` parameter. */
function arrowheadGlyph(value: string | undefined, atStart: boolean): ReactNode {
  const tip = atStart ? 4 : 16;
  const away = atStart ? 1 : -1;
  const caps: Record<string, ReactElement | null> = {
    none: null,
    arrow: <path d={`M${tip} 10l${4 * away} -3.4M${tip} 10l${4 * away} 3.4`} />,
    triangle: <path d={`M${tip} 10l${5 * away} -3.4v6.8z`} data-role="solid" />,
    inverted: <path d={`M${tip + 5 * away} 10l${-5 * away} -3.4v6.8z`} data-role="solid" />,
    square: <rect x={tip - (atStart ? 0 : 4)} y="7" width="4" height="6" data-role="solid" />,
    dot: <circle cx={tip + 2 * away} cy="10" r="2.6" data-role="solid" />,
    diamond: <path d={`M${tip} 10l${3 * away} -3l${3 * away} 3l${-3 * away} 3z`} data-role="solid" />,
    pipe: <path d={`M${tip} 6.5v7`} />,
    bar: <path d={`M${tip} 6.5v7`} />,
  };
  return (
    <Svg>
      <path d={atStart ? "M6 10h11" : "M3 10h11"} />
      {caps[value ?? "none"]}
    </Svg>
  );
}

/**
 * Every way a value can be previewed without a host renderer's help, keyed
 * by the family name a `ControlDefinition.glyph` names.
 *
 * WHY a lookup instead of a kind if-chain (ported verbatim,
 * AppearanceGlyph.tsx:54-63): a control's KIND is its identity; how its
 * values are drawn is a separate, shareable fact the registry entry
 * declares. Dispatching on kinds is how one donor renderer once missed a
 * routing branch and had its options drawn by the arrowhead renderer
 * instead. A new registry entry that previews like an existing one names its
 * family and touches nothing here; only a genuinely new drawing earns a new
 * entry — or, in the kit, a new key a host spreads in.
 *
 * `swatch` and `geo` are deliberately absent — see changes (1) and (2)
 * above.
 */
export const DEFAULT_GLYPH_FAMILIES: GlyphFamilies = {
  fill: FillGlyph,
  dash: DashGlyph,
  size: SizeGlyph,
  strokeWidth: StrokeWidthGlyph,
  font: FontGlyph,
  align: (value) => AlignGlyph(value, false),
  verticalAlign: (value) => AlignGlyph(value, true),
  routing: RoutingGlyph,
  arrowheadStart: (value) => arrowheadGlyph(value, true),
  arrowheadEnd: (value) => arrowheadGlyph(value, false),
};

/**
 * The one editor-coupled family, injected rather than baked in — see change
 * (2) above. `hexFor` resolves a palette name to a paintable colour; a name
 * with no resolution draws the same empty `data-mixed` swatch the donor drew
 * for a shape with no matching theme entry (ported, AppearanceGlyph.tsx:307-328).
 */
export function swatchGlyph(hexFor: (name: string) => string | undefined): GlyphRenderer {
  return (value) => {
    const fill = value ? hexFor(value) : undefined;
    return <span className="bbox-control-glyph-swatch" data-mixed={fill ? undefined : true} style={fill ? { background: fill } : undefined} />;
  };
}

// ── the paint face ─────────────────────────────────────────────────────────
//
// Ours, not the donor's. The archived app's triggers were a swatch (colour)
// or a fixed traced icon (line style); neither draws the RESULT. This family
// exists because of Zach's 2026-09-24 pick of the "Two Faces" proposal —
// three style triggers, "Inside", "Edge" and text — followed by:
//
//   "no need to put the text (inside and edge) on the drop down menu btw,
//    we can learn to just know it by the icon"
//
// WHY that sentence forces a drawn result rather than a nicer icon: with the
// words gone, the face is the ONLY thing distinguishing the two triggers. A
// paint-bucket and a line icon would name their families and say nothing
// about the shape you have selected, so the bar would read the same whether
// the fill were solid green or absent. A face that paints the actual fill
// treatment, colour and opacity answers "what is it now" at rest, which is
// what pays for dropping the labels.

/** What one face paints. Plain values — no editor, no shape, no engine. */
export interface FacePaint {
  /** Absent, or `hex: undefined`, draws the "no answer" face (a mixed
      selection), never a guess at one member's colour. */
  hex?: string;
  /** `solid` | `semi` | `pattern` | `none`, the fill treatment. Only read by
      an `inside` face. */
  fillStyle?: string;
  /** Painted stroke width in px. Only read by an `edge` face. */
  widthPx?: number;
  /** A `DASH_ARRAYS` key. Only read by an `edge` face. */
  dash?: string;
  /** 0–1. Applies to whichever half this face draws. */
  opacity?: number;
  /** The colour this face is painted ON, as a `#rrggbb` hex. An `edge` face
      compares its stroke against it to decide whether the stroke needs
      lifting off the surface at all (see `PaintFace`). Defaults to
      `PAINT_FACE_DEFAULT_SURFACE`, the pill's; a host that skins the trigger
      names its own surface here, the same seam as `ControlStrip`'s
      `triggerClassName`. */
  surface?: string;
}

/**
 * The surface an edge face assumes when its host names none: the pill's,
 * `PILL_SURFACE` in `floatingToolbar.tsx`.
 *
 * WHY a default at all, and why THIS one is trustworthy rather than a guess
 * the face has no business making: the paint faces exist for the pill's
 * triggers (the "Two Faces" section above — there is no other surface in
 * the kit that mounts one), and the pill's surface is the one colour the kit
 * ships FIXED in both colour schemes, by construction (`PILL_SURFACE`'s own
 * WHY: no token is left for a `prefers-color-scheme` block to flip). So the
 * default is not an assumption about an unknown host; it is the kit's own
 * constant restated, and `PaintFace.stories.tsx` pins the two literals
 * against each other so they cannot drift. Restated rather than imported
 * for the same reason `STROKE_WIDTH_PX` is (above): `floatingToolbar.tsx`
 * pulls the whole Base UI toolbar in, and a glyph module that imports a
 * toolbar to learn one hex would drag that into every registry item this
 * file ships in.
 *
 * WHY not measure the computed background behind the glyph, which would
 * "read" the surface instead of being told it: that is self-measurement,
 * the one thing CLAUDE.md's rule forbids a kit component ("props in, DOM
 * out"), and it would turn this module's plain render functions into a
 * hook-bearing component that paints one frame without the answer and a
 * second with it. A host that re-skins the pill passes `surface` — one
 * field, from the same place it already passes `hex`.
 */
export const PAINT_FACE_DEFAULT_SURFACE = "#1e1e1e";

/**
 * WCAG 2.x relative luminance of a `#rgb` / `#rrggbb` hex, or `undefined`
 * when the string is not one (a `rgb()` string, a palette NAME that never
 * resolved). Formula: WCAG 2.1 §1.4.3, "relative luminance" definition —
 * sRGB channels linearised at the 0.03928 knee, weighted 0.2126/0.7152/0.0722.
 */
function relativeLuminance(hex: string): number | undefined {
  const digits = hex.trim().replace(/^#/, "");
  const six =
    digits.length === 3 ? digits.split("").map((d) => d + d).join("") : digits.length === 6 ? digits : null;
  if (six === null || !/^[0-9a-fA-F]{6}$/.test(six)) return undefined;
  const channel = (offset: number) => {
    const c = Number.parseInt(six.slice(offset, offset + 2), 16) / 255;
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  };
  return 0.2126 * channel(0) + 0.7152 * channel(2) + 0.0722 * channel(4);
}

/** WCAG contrast ratio (1–21) between two hexes, `undefined` if either does
    not parse — the caller treats "unknown" as "assume the worst". */
export function contrastRatio(a: string, b: string): number | undefined {
  const la = relativeLuminance(a);
  const lb = relativeLuminance(b);
  if (la === undefined || lb === undefined) return undefined;
  return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
}

/** WCAG 1.4.11 (non-text contrast): the minimum a graphical mark needs
    against what it sits on. Below it the edge face lifts its stroke. */
export const EDGE_CONTRAST_MIN = 3;

/** The lift, in the face's 20-unit box: how far the ink hairline shows past
    EACH side of the coloured stroke, and how strongly. Half a unit is a hair
    at 24px, and half the ink (5.2:1 on the pill, well over the 3:1 floor)
    is the weight at which a black edge still reads as BLACK with a light
    rim rather than as a grey box — read off 4x captures of the running app,
    2026-09-25; 60% was the first cut and the rim swallowed the stroke. The
    mark stays "the rectangle", edged, not "a rectangle on a plate" (see the
    edge branch of `PaintFace`). */
const HAIRLINE_REACH = 0.5;
const HAIRLINE_OPACITY = 0.5;

/**
 * A trigger face that draws the selection's real paint.
 *
 * Injected the same way `swatchGlyph` is, and for the same reason: resolving
 * a palette name to a paintable colour needs the host's theme, which a kit
 * importing no canvas engine cannot reach. `read` receives the control's own
 * current value (the colour name, or `undefined` when the selection is
 * mixed) and returns everything else the face needs.
 */
export function paintFaceGlyph(
  part: "inside" | "edge",
  read: (value: string | undefined) => FacePaint,
): GlyphRenderer {
  return (value) => <PaintFace part={part} paint={read(value)} />;
}

function PaintFace({ part, paint }: { part: "inside" | "edge"; paint: FacePaint }) {
  const { hex, fillStyle, dash, opacity = 1 } = paint;
  // WHY the id is derived from the colour rather than `useId()`: two faces
  // that hatch the same hex want the SAME pattern, and a bare `id="hatch"`
  // on both would make every face resolve `url(#hatch)` to whichever mounted
  // last. Deriving it also keeps this module hook-free, so it stays the
  // plain render-function module the rest of the file is.
  const patternId = `bbox-face-hatch-${(hex ?? "none").replace("#", "")}`;
  // No resolved colour means a mixed selection: draw the empty face the
  // swatch family draws, never one member's colour standing in for all.
  const mixed = !hex;

  if (part === "inside") {
    const treatment = fillStyle ?? "solid";
    const body =
      mixed || treatment === "none" ? null : treatment === "pattern" ? (
        <>
          <pattern
            id={patternId}
            width="4"
            height="4"
            patternUnits="userSpaceOnUse"
            patternTransform="rotate(45)"
          >
            <line x1="0" y1="0" x2="0" y2="4" stroke={hex} strokeWidth="1.6" />
          </pattern>
          <rect x="3" y="3" width="14" height="14" rx="3" fill={`url(#${patternId})`} stroke="none" />
        </>
      ) : (
        <rect
          x="3"
          y="3"
          width="14"
          height="14"
          rx="3"
          fill={hex}
          // 0.28 is the alpha the mock's own `semi` face used, close enough
          // to tldraw's transparent fill to be recognised in a 24px cell.
          fillOpacity={treatment === "semi" ? 0.28 : 1}
          stroke="none"
        />
      );
    return (
      <svg viewBox="0 0 20 20" className="bbox-control-glyph" aria-hidden="true" opacity={opacity}>
        {body}
        {/* The keyline is what stops an empty or transparent face reading as
            a rendering failure — there is still a square there. */}
        <rect
          x="3"
          y="3"
          width="14"
          height="14"
          rx="3"
          fill="none"
          stroke="currentColor"
          strokeWidth="1"
          opacity={0.5}
        />
        {/* A mixed selection gets the swatch family's diagonal slash
            (`controlGlyphs.css`'s `[data-mixed]`), and "no fill" does not.
            They were separated only by a keyline opacity of 0.5 vs 0.35 —
            two states that mean "definitely nothing" and "we don't know",
            told apart by a shade. Caught by an audit of this file, not by a
            test: nothing here asserts on how two faces DIFFER.

            No `strokeWidth` on the slash on purpose: `controlGlyphs.css`'s
            `[data-role="slash"]` rule sets 1.5, and a CSS rule outranks a
            presentation attribute — an authored number here would be a number
            this never paints. */}
        {mixed ? (
          <path d="M5 15 15 5" stroke="currentColor" opacity="0.75" data-role="slash" />
        ) : null}
      </svg>
    );
  }

  const widthPx = paint.widthPx ?? 2;
  // The face is a 20-unit box standing for a shape that may be 400px wide, so
  // the real width is compressed rather than reproduced: a 7px "thick" edge
  // drawn at 7 units would swallow the face whole. The ladder stays monotonic,
  // which is the property the face has to preserve.
  const drawn = Math.max(1, Math.min(3.4, 0.9 + widthPx * 0.36));
  const array = dash ? DASH_ARRAYS[dash] : undefined;
  const painted = !mixed && dash !== "none";

  // WHY the lift is CONDITIONAL, and on a measured number: the face used to
  // draw a `currentColor` keyline under every coloured stroke, 1.6 units
  // wider than the stroke at 22% ink — a grey plate the stroke sat on. Zach,
  // 2026-09-25: "I don't like the grey background behind the edge. ideally
  // the edge is rendered as if it itself was just the rectangle you are
  // formatting.. you wouldn't see that background." So a stroke that can be
  // seen on its own is drawn ALONE — for twelve of tldraw's thirteen palette
  // colours in light mode and all thirteen in dark, the face is the rectangle
  // and nothing else.
  //
  // The tempting fix was to delete the keyline outright, and that ships the
  // bug it existed for straight back: measured in the running app, a fresh
  // geo's edge is tldraw's light-mode `black` (#1d1d1d) and the pill is
  // #1e1e1e — 1.01:1 — so a bare black stroke on the bar is invisible and
  // the trigger reads as a lone chevron. The other tempting fix, a thinner
  // plate, keeps a plate. So: compute the stroke's contrast against the
  // surface it is actually on, and only when it misses WCAG's 3:1 graphics
  // floor add the least that makes the stroke findable — a hairline of the
  // surface's own ink hugging the mark's exact shape (same path, same dash,
  // same cap, half a unit past each side), painted under it. It reads as the
  // rectangle's own edge, not as something behind it. A hex that does not
  // parse counts as failing: lifting a stroke that did not need it costs a
  // hairline; not lifting one that did costs the whole face.
  const surface = paint.surface ?? PAINT_FACE_DEFAULT_SURFACE;
  const contrast = painted && hex ? contrastRatio(hex, surface) : undefined;
  const lifted = painted && !(contrast !== undefined && contrast >= EDGE_CONTRAST_MIN);

  // One mark, drawn twice at most: once as the ink hairline (when lifted),
  // once in the selection's colour on top. Sharing the geometry is what
  // guarantees the hairline can never be a different shape from the stroke.
  const mark = (
    stroke: string,
    strokeWidth: number,
    stamp: { "data-dash": string | undefined } | { "data-role": "hairline"; strokeOpacity: number },
  ): ReactNode =>
    dash === "draw" ? (
      <g fill="none" stroke={stroke} strokeWidth={strokeWidth} strokeLinecap="round" {...stamp}>
        {/* WHY four separate strokes that OVERSHOOT and cross at the corners,
            not a wobbled outline: the wobble shipped first and was
            indistinguishable from `solid` at 24px — a 14-unit box cannot
            carry a deviation small enough to look like a hand and large
            enough to see. Gaps at the corners were the second attempt and
            did not survive contact with the round caps: at the thick rung
            the cap radius is 1.7 units and the gaps were 1, so the caps
            closed them and the face was a rounded rect again. Crossing
            cannot be closed by a cap, so it reads at every width, and it is
            what a sketched box actually looks like. */}
        <path d="M4.0 3.8 16.4 2.9" />
        <path d="M16.0 3.6 17.0 16.2" />
        <path d="M16.2 16.0 3.7 17.0" />
        <path d="M4.0 16.4 3.0 3.9" />
      </g>
    ) : (
      <rect
        x="3"
        y="3"
        width="14"
        height="14"
        rx="3"
        fill="none"
        stroke={stroke}
        strokeWidth={strokeWidth}
        strokeDasharray={array}
        strokeLinecap={dash === "dotted" ? "round" : "butt"}
        {...stamp}
      />
    );

  return (
    <svg viewBox="0 0 20 20" className="bbox-control-glyph" aria-hidden="true" opacity={opacity}>
      {/* `none` and `mixed` paint NO colour, so a neutral keyline IS the face.
          `none` first shipped as a 1px dashed stroke in the edge's own colour,
          which on a green shape read as "a thin dashed green edge" — the one
          thing it does not mean; the ink keyline alone is the honest drawing
          of "there is no edge", and without it the trigger is a bare chevron
          that reads as a rendering failure. `mixed` adds the swatch family's
          diagonal slash so "we don't know" cannot be confused with "there is
          no edge". Every one of these was read off a contact sheet rather
          than reasoned about. */}
      {painted ? null : (
        <rect
          x="3"
          y="3"
          width="14"
          height="14"
          rx="3"
          fill="none"
          stroke="currentColor"
          strokeOpacity={0.45}
          strokeWidth={1.2}
          data-role="keyline"
        />
      )}
      {mixed ? <path d="M5 15 15 5" stroke="currentColor" opacity="0.75" data-role="slash" /> : null}
      {lifted
        ? mark("currentColor", drawn + 2 * HAIRLINE_REACH, {
            "data-role": "hairline",
            strokeOpacity: HAIRLINE_OPACITY,
          })
        : null}
      {painted ? mark(hex!, drawn, { "data-dash": dash }) : null}
    </svg>
  );
}

// src/editor/controlPanel.tsx — ported from SystemSketch, read-only
// donor at /home/bam/systemsketch, revision
// `10748b8ccdb374e71714f3d351abc43947ecfb0e`:
//
//   • `src/contextualMenus/ContextualControls.tsx:251-401` — `ControlPanel`
//     (unrenamed), `OptionButton` (renamed `ControlOptionButton`).
//   • `src/contextualMenus/ContextualControls.tsx:455-500` — `CustomFontSizeCell`
//     (unrenamed).
//
// WHAT CHANGED in the port, exhaustively:
//
//   1. `useValue` (tldraw's reactive read) is gone — see `controlStrip.tsx`'s
//      own change (4) for the full rationale. `onPresetRungs` was
//      `customSize.onPresetRungs()`, a thunk re-invoked per render; it is
//      now the plain field `customSize.onPresetRungs`, read directly.
//   2. `CustomColorCell`/`CustomColorPicker` (donor :403-453) do not port —
//      out of scope by design (task brief: "Do NOT port CustomColorPicker").
//      `ControlPanel` takes a `customColorSlot?: ReactNode` prop instead:
//      when a control declares `custom: true`, this cell renders whatever
//      the host passes (a future real colour picker) or, absent a slot, a
//      purely decorative placeholder (`DefaultCustomColorSwatch` below) so
//      the layout still reads correctly with nothing wired up yet. The rule
//      that matters travels unchanged: the cell renders ONLY when
//      `control.custom` is true, exactly the same guard `CustomFontSizeCell`
//      below applies to `control.customSize`.
//   3. `formatFontPx` does not port (see `controlStrip.tsx`'s change 6); its
//      one rounding rule is the same local `formatPx` helper `controlStrip
//      .tsx` already defines — re-declared here rather than imported
//      because the two files must not import from each other (`ControlPanel`
//      is a leaf `ControlStrip` composes, never the reverse) and a
//      six-line pure function is cheaper duplicated than plumbed through a
//      new shared module outside this lane's write set.
//   4. THE PANEL PAINTS IN ITS SURFACE'S INK, NEVER IN A PAGE TOKEN
//      (2026-09-25). The port wrote its colours in shadcn's vocabulary —
//      `text-foreground`, `hover:bg-muted`, `bg-primary`, `border-border`,
//      `text-muted-foreground` — every one a PAGE token that flips with
//      `prefers-color-scheme`. But the panel is skinned by its host
//      (`ControlStrip`'s `panelClassName`; the pill passes `PILL_POPOVER`),
//      and the pill's surface is a FIXED #1e1e1e in both schemes. Measured in
//      the running app, light scheme, the Shape picker Zach photographed:
//      label #0a0a0a on #1e1e1e, 1.19:1; the list layout's check marks the
//      same 1.19:1; hover a near-white `oklch(0.97)` chip cut out of the dark
//      panel; the chosen chip `oklch(0.205)`, a shade darker than the panel
//      it sat on. Dark scheme read 15.97:1 throughout, which is why nobody
//      saw it until Zach opened the app in light mode.
//      The donor hit the identical bug one level up (its `.systemsketch-
//      appearance__trigger-px` and `__option:hover`, appearance.css:66-73 and
//      :180-186) and fixed it the same way this does: the panel's contents
//      INHERIT the surface's ink — `currentColor` — and derive every tint from
//      it (`color-mix` at 10% for hover, 60% for muted text, 15-20% for
//      rules), so a host that skins the surface gets readable contents for
//      free and a host that does not still gets the theme's, because the
//      unskinned popover's ink IS the theme's `popover-foreground`. The chosen
//      chip inverts — ink for its fill, the surface for its text, read off
//      `--bbox-pill-surface` (declared by `PILL_SURFACE`) with the theme's
//      `--popover` as the unskinned fallback — so its contrast is the panel's
//      own by construction. The tempting wrong fix was the host's: restate the
//      colours in `selectionClusters.tsx`'s `ON_PILL` and pass them down as
//      one more class string. That fixes one host's one skin and leaves the
//      next host to rediscover it (feedback.md, 2026-09-19: chrome fixes land
//      in the kit, the host only mounts and configures).
//
// Everything else — stacked-modes-outermost-last via `stackModes`
// (`controlRegistry.ts`), the beside-mode divider, the swatch ring styling,
// the list layout's check-mark-only selection, the automatic-option "A"
// badge, the custom px cell's Enter/blur commit and revert-on-invalid-input
// contract — is unchanged behaviour.
"use client";

import { useEffect, useState, type ReactNode } from "react";
import { Check } from "lucide-react";

import { cn } from "../lib/utils";
import type { GlyphFamilies } from "./controlGlyphs";
import {
  MIXED_LABEL,
  stackModes,
  type BoundControl,
  type ContinuousBinding,
  type ControlLayout,
  type ControlOption,
  type CustomSizeBinding,
} from "./controlRegistry";

/**
 * Secondary text — a rung's px, the Custom cell's words, the slider's label
 * and readout — as the surface's ink at 60%, never `text-muted-foreground`
 * (change 4). The donor mutes its trigger px the same way, at 55%
 * (appearance.css:73); 60% is what keeps 11px tabular digits above 4.5:1 on
 * both the pill (#a5a5a5 on #1e1e1e, 7.0:1) and an unskinned light popover
 * (#666 on white, 5.7:1).
 */
const MUTED_INK = "text-current/60";

export interface ControlPanelProps<K extends string = string> {
  control: BoundControl<K>;
  glyphs: GlyphFamilies;
  /** Where a real colour picker lands later (out of scope here by design —
      see change 2 above). Ignored unless `control.custom` is true. */
  customColorSlot?: ReactNode;
  testIdPrefix?: string;
}

/** The popover body every popover-bearing trigger in `controlStrip.tsx`
    opens — one renderer for `swatches` / `row` / `chips` / `list` /
    `library`, chosen entirely by `data-layout`, never by `control.kind`. */
export function ControlPanel<K extends string>({
  control,
  glyphs,
  customColorSlot,
  testIdPrefix = "bbox",
}: ControlPanelProps<K>) {
  const beside = Boolean(control.modeControl) && control.modePlacement === "beside";
  const options = control.automaticOption ? [control.automaticOption, ...control.options] : control.options;
  const customSize = control.customSize;
  // A custom scale on any participant means no preset row is truthfully
  // "current" — see `ControlOptionButton`'s `forceUnchecked`.
  const onPresetRungs = customSize ? customSize.onPresetRungs : true;
  const sections = beside ? [control.modeControl!] : stackModes(control);

  return (
    <div
      data-slot="control-panel"
      role="menu"
      aria-label={control.label}
      data-layout={control.layout}
      data-mode={control.modeControl ? control.modePlacement : undefined}
      data-testid={testIdPrefix ? `${testIdPrefix}-control-panel-${control.id}` : undefined}
      className={cn("flex min-w-0 flex-col gap-2", beside && "flex-row items-center")}
    >
      {sections.map((section) => (
        <div
          key={section.id}
          role="group"
          aria-label={section.label}
          data-mode-control={section.id}
          data-mode-layout={section.layout}
          className={cn(
            "flex flex-wrap items-center gap-2",
            // The rule between a mode section and the options is the ink at
            // 15%, not `border-border` — see change 4: in light mode
            // `--border` is a bright `oklch(0.922)` line across a #1e1e1e
            // panel. Ink at 15% on the pill is #3a3a3a, FigJam's own traced
            // #383838 divider to within a shade.
            beside
              ? "min-h-7"
              : "-mx-2.5 border-b border-current/15 px-2.5 pb-2 first:-mt-0.5",
          )}
        >
          {section.options.map((option) => (
            <ControlOptionButton
              key={option.value}
              control={section}
              option={option}
              glyphs={glyphs}
              // The same rule the main option group uses below: a `row` is
              // icons only, anything else carries its name — what lets one
              // registered control render as labelled chips stacked on a
              // shape and as a bare icon row beside a connector's line
              // styles (ContextualControls.tsx:300-304, ported verbatim).
              withLabel={!beside && section.layout !== "row"}
            />
          ))}
        </div>
      ))}
      {beside ? <div aria-hidden="true" className="-my-2.5 w-px self-stretch bg-current/15" /> : null}
      <div
        role="group"
        aria-label={control.label}
        className={optionsGroupClass(control.layout)}
        style={
          control.columns ? { gridTemplateColumns: `repeat(${control.columns}, 1.5rem)` } : undefined
        }
      >
        {options.map((option) => (
          <ControlOptionButton
            key={option.value}
            control={control}
            option={option}
            glyphs={glyphs}
            withLabel={control.layout !== "row" && control.layout !== "swatches"}
            forceUnchecked={Boolean(customSize) && !onPresetRungs}
          />
        ))}
        {control.custom ? <CustomColorCell slot={customColorSlot} /> : null}
      </div>
      {/* Load-bearing (task brief): renders ONLY when the binding supplied a
          `customSize` — a surface bound to an explicit target (a block
          title) that never wires one gets presets-only, never a dead Custom
          cell. That bug already shipped once in the donor. */}
      {customSize ? <CustomFontSizeCell binding={customSize} /> : null}
      {/* Same rule as the Custom cell above: renders ONLY when the binding
          supplied one, so a control with no continuous channel never shows a
          dead slider. */}
      {control.continuous ? <ContinuousRow binding={control.continuous} /> : null}
    </div>
  );
}

function optionsGroupClass(layout: ControlLayout): string {
  switch (layout) {
    case "swatches":
      return "grid grid-cols-10 gap-2 self-start p-1";
    case "row":
      return "flex flex-wrap items-center gap-2";
    case "chips":
      return "flex flex-wrap items-center gap-1 p-1";
    case "list":
      return "flex flex-col";
    case "library":
      return "grid grid-cols-5 gap-0.5 max-h-64 overflow-y-auto overscroll-contain";
  }
}

function ControlOptionButton<K extends string>({
  control,
  option,
  glyphs,
  withLabel,
  forceUnchecked,
}: {
  control: BoundControl<K>;
  option: ControlOption;
  glyphs: GlyphFamilies;
  withLabel?: boolean;
  /** A custom scale is applied elsewhere on this target, so no preset row
      is truthfully "current" (donor's own name for the flag, kept). */
  forceUnchecked?: boolean;
}) {
  const isCurrent =
    !forceUnchecked && control.value?.type === "shared" && control.value.value === option.value;
  const automatic = control.automaticOption?.value === option.value;
  const rungPx = control.rungPxByValue?.[option.value];
  const list = control.layout === "list";
  const swatches = control.layout === "swatches";

  return (
    <button
      type="button"
      role="menuitemradio"
      aria-checked={isCurrent}
      aria-label={option.label}
      title={option.label}
      data-control={control.id}
      data-kind={control.kind}
      data-value={option.value}
      onClick={() => control.onSelect(option.value)}
      className={cn(
        // `text-inherit`, and it is the whole of change 4 (file header): the
        // option paints in whatever ink the surface under it set, never in
        // the page's `text-foreground` — which is #0a0a0a in light mode and
        // put every label on the pill's #1e1e1e panel at 1.19:1. Written out
        // rather than left to preflight's `button { color: inherit }` so the
        // rule is visible at the seam it protects.
        "flex shrink-0 cursor-pointer items-center border-0 bg-transparent p-0 text-inherit",
        optionButtonClass(control.layout),
        isCurrent && selectedOptionClass(control.layout),
        // Hover is the ink at 10% — the donor's own rule (appearance.css:186),
        // and on the pill it lands on #353535, FigJam's traced #383838 to
        // within a shade. `hover:bg-muted` was `oklch(0.97)` in light mode: a
        // white chip cut out of the dark panel under the cursor.
        !isCurrent && "hover:bg-current/10",
      )}
    >
      {list ? (
        <Check
          aria-hidden="true"
          className={cn("size-4 shrink-0", isCurrent ? "opacity-100" : "opacity-0")}
        />
      ) : null}
      {automatic ? (
        <span
          aria-hidden="true"
          className={cn(
            "flex size-6 shrink-0 items-center justify-center font-mono text-xs font-extrabold",
            swatches && isCurrent && "rounded-full ring-2 ring-current",
          )}
        >
          A
        </span>
      ) : (
        <span
          aria-hidden="true"
          className={cn(
            "flex shrink-0 items-center justify-center",
            swatches ? "size-6 rounded-full" : "size-6",
          )}
        >
          {control.glyph ? glyphs[control.glyph]?.(option.value) : null}
        </span>
      )}
      {withLabel ? <span className="min-w-0 flex-1 truncate text-left text-sm">{option.label}</span> : null}
      {withLabel && rungPx !== undefined && rungPx !== null ? (
        <span
          data-testid={`control-option-rung-px-${option.value}`}
          className={cn("ml-auto shrink-0 pl-2 text-xs tabular-nums", MUTED_INK)}
        >
          {formatPx(rungPx)}
        </span>
      ) : null}
    </button>
  );
}

function optionButtonClass(layout: ControlLayout): string {
  switch (layout) {
    case "swatches":
      return "size-6 justify-center rounded-full";
    case "row":
      return "size-6 justify-center rounded-md";
    case "chips":
      return "h-6 gap-1.5 rounded-md px-2";
    case "list":
      return "h-6 min-w-0 gap-1.5 rounded-md px-1.5";
    case "library":
      return "h-8 min-w-8 justify-start gap-2 rounded-lg px-1.5";
  }
}

/**
 * The chosen state per layout. `swatches` rings the disc rather than filling
 * its cell (FigJam draws the ring two pixels off the swatch's own edge —
 * appearance.css's own comment); every other layout fills, matching a
 * labelled chip's own selected state.
 *
 * WHY the fill is the ink INVERTED rather than `bg-primary` (change 4): on
 * the pill in light mode `--primary` is `oklch(0.205)`, one shade darker
 * than the #1e1e1e panel — the chosen chip was there and could not be seen.
 * Ink for the chip and the surface for its text gives the chip exactly the
 * panel's own contrast, whatever the skin, and on an unskinned popover it
 * resolves to the very pair `bg-primary text-primary-foreground` did
 * (near-black on white in light, near-white on `oklch(0.205)` in dark) — so
 * nothing moves where the tokens were right. Both colours are read off the
 * `--bbox-pill-ink` / `--bbox-pill-surface` pair `PILL_SURFACE` declares,
 * falling back to the theme's own popover pair for an unskinned panel.
 *
 * WHY not `bg-current` for the fill, which looks like the obvious "the ink"
 * spelling: `currentColor` is the element's OWN computed `color`, and this
 * same class list sets that to the surface — so the chip painted surface on
 * surface. Measured in the running app: chip `rgb(30,30,30)`, text
 * `rgb(30,30,30)`, 1:1. The ink has to be named from outside the element.
 *
 * WHY the swatch ring needs no `ring-offset`: the button is 24px and the
 * swatch inside it 20px, so the ring drawn at the button's own edge already
 * sits two pixels off the swatch — FigJam's gap — with the REAL surface
 * showing through. `ring-offset-popover` painted a light-mode-white gap
 * around the chosen swatch on the dark panel.
 */
function selectedOptionClass(layout: ControlLayout): string {
  if (layout === "swatches") return "ring-2 ring-current";
  // `list` marks a chosen row with the check mark alone (donor's own WHY,
  // carried forward): filling its background would put the row back on the
  // popover surface's own ink where a check has already said "selected."
  if (layout === "list") return "";
  return "bg-[var(--bbox-pill-ink,var(--popover-foreground))] text-[var(--bbox-pill-surface,var(--popover))]";
}

/**
 * Not part of the design's props sketch, added here to answer "what renders
 * in the 22nd cell before a host wires `customColorSlot`": a purely
 * decorative rainbow disc, the same shape the donor drew idle
 * (figjamTokens.ts's `CUSTOM_WHEEL`).
 */
function CustomColorCell({ slot }: { slot?: ReactNode }) {
  return (
    <span
      data-slot="control-custom-color"
      className="-m-1 flex size-8 shrink-0 items-center justify-center"
    >
      {slot ?? <DefaultCustomColorSwatch />}
    </span>
  );
}

function DefaultCustomColorSwatch() {
  return (
    <span
      aria-hidden="true"
      className="block size-6 rounded-full shadow-[inset_0_0_0_1px_rgba(255,255,255,0.2)]"
      // WHY inline style despite the house "never raw style={{color}} for
      // theming" rule: a colour wheel is not a THEME colour, it is a fixed
      // physical fact (the visible spectrum) that is identical in every
      // skin — the donor never made its own equivalent constant
      // (figjamTokens.ts's `CUSTOM_WHEEL`) a CSS variable either. This is
      // only ever the placeholder for `customColorSlot`; the moment a host
      // wires a real picker in, this never renders again.
      style={{
        background:
          "conic-gradient(#f00,#ffa800 47.73deg,#ff0 79.56deg,#0f0 121.33deg,#0ff 180.99deg,#00f 238.67deg,#f0f 294.36deg,#f00 360deg)",
      }}
    />
  );
}

function CustomFontSizeCell({ binding }: { binding: CustomSizeBinding }) {
  const sharedText = typeof binding.sharedPx === "number" ? formatPx(binding.sharedPx) : "";
  const [draft, setDraft] = useState(sharedText);
  useEffect(() => setDraft(sharedText), [sharedText]);

  const commit = () => {
    const parsed = Number.parseFloat(draft);
    if (!Number.isFinite(parsed)) {
      setDraft(sharedText);
      return;
    }
    binding.applyPx(parsed);
  };

  return (
    <label className="mx-1 mt-1 flex items-center gap-2 rounded-md border border-current/20 px-2 py-1 text-sm">
      <span className={MUTED_INK}>Custom</span>
      <input
        data-testid="control-custom-size-input"
        type="number"
        min={binding.minPx}
        max={binding.maxPx}
        step={1}
        value={draft}
        placeholder={binding.sharedPx === "mixed" ? MIXED_LABEL : undefined}
        onChange={(event) => setDraft(event.target.value)}
        onBlur={commit}
        onKeyDown={(event) => {
          if (event.key === "Enter") {
            event.preventDefault();
            commit();
          }
        }}
        className="w-full min-w-0 flex-1 bg-transparent text-right outline-none"
      />
      <span className={MUTED_INK}>px</span>
    </label>
  );
}

/**
 * The continuous channel's row — a slider and its readout, under the
 * options.
 *
 * WHY it lives in the panel rather than on the strip: opacity is an
 * attribute OF a paint, not a peer of it (Zach, 2026-09-24). The archived
 * app put it on the pill, arguing its current state is what you need to see
 * while you drag — true, and the readout beside the slider is what answers
 * that, without spending a slot on the bar for something that only applies
 * once you have already opened the paint you are fading.
 *
 * WHY `continuous: true` on input and a settling call on release: a range
 * input fires `input` per pixel. Marking every one of those as its own undo
 * step would make one drag cost forty presses of ⌘Z.
 */
function ContinuousRow({ binding }: { binding: ContinuousBinding }) {
  const shared = typeof binding.value === "number" ? binding.value : null;
  const [draft, setDraft] = useState(shared);
  useEffect(() => setDraft(shared), [shared]);
  const shown = draft ?? shared;

  return (
    <label
      data-slot="control-continuous"
      className="mx-1 mt-1 flex items-center gap-2 px-1 py-1 text-sm"
    >
      <span className={cn("shrink-0", MUTED_INK)}>{binding.label}</span>
      <input
        data-testid="control-continuous-input"
        type="range"
        min={binding.min}
        max={binding.max}
        step={binding.step ?? 1}
        // A mixed target has no one value to park the thumb at; the readout
        // says so and the slider sits at the low end rather than inventing a
        // number the selection does not have.
        value={shown ?? binding.min}
        aria-label={binding.label}
        aria-valuetext={shown === null ? MIXED_LABEL : binding.format(shown)}
        onChange={(event) => {
          const next = Number(event.target.value);
          setDraft(next);
          binding.apply(next, { continuous: true });
        }}
        onPointerUp={(event) => binding.apply(Number(event.currentTarget.value))}
        onKeyUp={(event) => binding.apply(Number(event.currentTarget.value))}
        className="min-w-24 flex-1 accent-[var(--bbox-control-accent,currentColor)]"
      />
      <output className={cn("w-10 shrink-0 text-right tabular-nums", MUTED_INK)}>
        {shown === null ? MIXED_LABEL : binding.format(shown)}
      </output>
    </label>
  );
}

/** Ours, ad hoc — see `controlStrip.tsx`'s change 6 and this file's own
    change 3: the one rounding rule of the donor's `formatFontPx`, not that
    function's live-scale plumbing. */
function formatPx(px: number): string {
  const rounded = Math.round(px * 10) / 10;
  return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(1);
}

