export interface ControlStripProps<K extends string = string> {
  composition: ControlComposition<K>;
  glyphs: GlyphFamilies;
  /** Popover plumbing for every `ControlPanel` this strip opens — the
      kit's universal host contract (MENU-KIT-DESIGN.md §4): a portal target
      inside the host's own token scope. */
  container?: HTMLElement | null;
  /** `false` while a live text editor elsewhere on the surface must keep
      its own focus (a block-title rename field, a colour hex input) — see
      `popover.tsx`'s own header for why this is a boolean, not the donor's
      two-popover-implementations split. */
  autoFocus?: boolean;
  /** The "this pointer event is mine" seam (tldraw's own
      `editor.markEventAsHandled`, or nothing for a host with no such
      concept) — wired onto every panel's own pointer-down-capture. */
  onPanelPointerDownCapture?: PointerEventHandler;
  /**
   * The host's colour picker, rendered into the 22nd cell of any `swatches`
   * control that declares `custom` — screenshot 01's rainbow well.
   *
   * WHY this had to exist here and not only on `ControlPanel`: the panel
   * already accepted `customColorSlot`, but `ControlStrip` — the component
   * every host actually renders, and the only thing that constructs the
   * panels — never exposed or forwarded it. So the well was unreachable in
   * practice: an independent judge opened the fill popover and found the
   * rainbow cell was an `aria-hidden` span with no interaction behind it,
   * with the only real buttons being preset swatches. A slot nothing can
   * fill is indistinguishable from a decoration, which is exactly what it
   * had become.
   *
   * Still omittable: with no slot the cell stays the placeholder it is
   * today, because the picker itself is deliberately a separate port (kit
   * omission list) and shipping a half-picker would be worse than shipping
   * the seam for one.
   */
  customColorSlot?: ReactNode;
  /**
   * Render as a GROUP inside a toolbar the caller already established,
   * instead of as a toolbar root of its own. Default false.
   *
   * WHY this is a prop the caller sets rather than something the component
   * works out: two nested Base UI `Toolbar.Root`s own two separate
   * roving-focus groups, so a strip composed inside `FloatingToolbar`
   * alongside sibling buttons split arrow-key navigation in half. The first
   * repair detected nesting from React context — which is UNSOUND, because
   * context crosses portals and the DOM does not, so a host calling
   * `createPortal` got a strip rendering as a group with no toolbar ancestor
   * and leaking focus out of its own popup. That was a REGRESSION against
   * behaviour which had been correct, and patching the kit's own portal
   * wrappers could never cover a portal the kit does not own.
   *
   * There is no sound way to infer this, so it is declared. The caller knows
   * what it composed; the component cannot. Defaulting to false means the
   * standalone case — including any host portal — behaves exactly as it did
   * before any of this existed.
   */
  nested?: boolean;
  testIdPrefix?: string;
  /** Not in the design doc's props sketch, added here because this
      component wraps `Toolbar` (`toolbar.tsx`), which — like every Base UI
      roving-focus container — wants an accessible name. Every other kit
      surface with the same shape (`ChromeBar`, `ToolDock`) takes its own
      `"aria-label"`; this one was simply the first to be built. */
  "aria-label"?: string;
  /** The host's skin for every panel this strip opens.
   *
   * WHY a prop and not the host's problem: a panel portals OUT of the strip,
   * so a wrapper's classes cannot reach it and the panel lands in the app's
   * page theme rather than the bar's. The trunk already exports `PILL_POPOVER`
   * (`floatingToolbar.tsx`) for exactly this; this is where a host passes it. */
  panelClassName?: string;
  /** The host's skin for every TRIGGER in this strip.
   *
   * Same seam as `panelClassName`, one level up. The kit's `ToolbarButton`
   * offers `sm`/`default`/`lg` (h-7/h-8/h-9, `rounded-lg`), and a host whose
   * bar is traced from another product may need a cell no size value can
   * reach — this app's is 40x5, measured off FigJam. Without this the four
   * kit triggers rendered 32px tall with a 10px radius beside the app's own
   * 40/5 cells, on one bar. */
  triggerClassName?: string;
}

/** One renderer for every registered control, regardless of target surface
    (donor's own one-line summary, ContextualControls.tsx:54, still true). */
export function ControlStrip<K extends string>({
  composition,
  glyphs,
  container,
  autoFocus,
  onPanelPointerDownCapture,
  customColorSlot,
  nested = false,
  testIdPrefix = "bbox",
  panelClassName,
  triggerClassName,
  "aria-label": ariaLabel,
}: ControlStripProps<K>) {
  const Root = nested ? ToolbarGroup : Toolbar;
  return (
    <Root
      aria-label={ariaLabel}
      data-slot="control-strip"
      // WHY two names on the same value: MENU-KIT-DESIGN.md §3.3 names the
      // rename `data-contextual-recipe` → `data-control-recipe`; the task
      // brief handed to this lane says the ORIGINAL name "survives... tests
      // assert on which recipe rendered." Both cannot be half-honored by
      // guessing, so this ships both attributes rather than picking a
      // string a downstream test might be keyed to sight-unseen — a
      // decision for whoever wires the first real host, not a coin flip
      // here.
      data-contextual-recipe={composition.id}
      data-control-recipe={composition.id}
      data-testid={testIdPrefix ? `${testIdPrefix}-control-strip` : undefined}
      className="flex-wrap"
    >
      {composition.groups.map((group, index) => (
        <Fragment key={group.id}>
          {/* `composeControls` (controlRegistry.ts) never emits a group with
              zero controls, so this separator can never hang over an empty
              gap — the elision happens upstream, once, not here per-render. */}
          {index > 0 ? <ToolbarSeparator /> : null}
          <ToolbarGroup data-contextual-group={group.id}>
            {group.controls.map((control) => (
              <ControlTriggerItem
                key={control.id}
                control={control}
                glyphs={glyphs}
                container={container}
                autoFocus={autoFocus}
                onPanelPointerDownCapture={onPanelPointerDownCapture}
                customColorSlot={customColorSlot}
                testIdPrefix={testIdPrefix}
                panelClassName={panelClassName}
                triggerClassName={triggerClassName}
              />
            ))}
          </ToolbarGroup>
        </Fragment>
      ))}
    </Root>
  );
}

interface TriggerShapeProps<K extends string> {
  control: BoundControl<K>;
  glyphs: GlyphFamilies;
  container?: HTMLElement | null;
  autoFocus?: boolean;
  onPanelPointerDownCapture?: PointerEventHandler;
  /** Forwarded unchanged from `ControlStripProps.customColorSlot` — only the
      panel of a `custom` swatches control ever renders it. */
  customColorSlot?: ReactNode;
  /**
   * Render as a GROUP inside a toolbar the caller already established,
   * instead of as a toolbar root of its own. Default false.
   *
   * WHY this is a prop the caller sets rather than something the component
   * works out: two nested Base UI `Toolbar.Root`s own two separate
   * roving-focus groups, so a strip composed inside `FloatingToolbar`
   * alongside sibling buttons split arrow-key navigation in half. The first
   * repair detected nesting from React context — which is UNSOUND, because
   * context crosses portals and the DOM does not, so a host calling
   * `createPortal` got a strip rendering as a group with no toolbar ancestor
   * and leaking focus out of its own popup. That was a REGRESSION against
   * behaviour which had been correct, and patching the kit's own portal
   * wrappers could never cover a portal the kit does not own.
   *
   * There is no sound way to infer this, so it is declared. The caller knows
   * what it composed; the component cannot. Defaulting to false means the
   * standalone case — including any host portal — behaves exactly as it did
   * before any of this existed.
   */
  nested?: boolean;
  testIdPrefix: string;
  panelClassName?: string;
  triggerClassName?: string;
}

/**
 * The lookup itself (change 1 above). `TriggerShapeProps<K>`'s generic can't
 * survive being stored as a plain `Record` value (a mapped type can't carry
 * a distinct type parameter per key), so each entry is typed loosely and
 * re-pinned to the caller's own `K` with a cast at the one call site below —
 * documented here rather than silently `any`-ed.
 */
type TriggerShapeComponent = (props: TriggerShapeProps<string>) => ReactNode;

function ControlTriggerItem<K extends string>(props: TriggerShapeProps<K>) {
  const Shape = TRIGGER_SHAPES[props.control.trigger] as unknown as (
    props: TriggerShapeProps<K>,
  ) => ReactNode;
  return <Shape {...props} />;
}

function ToggleTrigger<K extends string>({ control, glyphs, testIdPrefix }: TriggerShapeProps<K>) {
  const pressed = control.value?.type === "shared" && control.value.value === "on";
  const face = control.glyph ? glyphs[control.glyph]?.(pressed ? "on" : "off") : undefined;
  return (
    <ToolbarButton
      aria-label={control.label}
      title={control.label}
      aria-pressed={pressed}
      data-control={control.id}
      data-kind={control.kind}
      data-testid={testIdPrefix ? `${testIdPrefix}-control-${control.id}` : undefined}
      onClick={() => control.onSelect(pressed ? "off" : "on")}
    >
      {/* See change 2 above: the label-initial fallback reproduces the
          donor's hardcoded "B" for `bold` with no hardcoded string here. */}
      {face ?? (
        <strong aria-hidden="true" className="font-sans text-base">
          {control.label.charAt(0).toUpperCase()}
        </strong>
      )}
    </ToolbarButton>
  );
}

function ActionTrigger<K extends string>({ control, glyphs, testIdPrefix }: TriggerShapeProps<K>) {
  const face = control.glyph ? glyphs[control.glyph]?.(undefined) : undefined;
  return (
    <ToolbarButton
      aria-label={control.label}
      title={control.label}
      data-control={control.id}
      data-kind={control.kind}
      data-testid={testIdPrefix ? `${testIdPrefix}-control-${control.id}` : undefined}
      onClick={() => control.onSelect()}
    >
      {face}
    </ToolbarButton>
  );
}

/** Shared by the three popover-bearing trigger shapes (`value`/`icon`/`text`)
    — the disclosure mechanics are identical; only the trigger's own FACE
    (drawn by `TriggerFace` below) varies by `control.trigger`. */
function PopoverTriggerShape<K extends string>({
  control,
  glyphs,
  container,
  autoFocus,
  onPanelPointerDownCapture,
  customColorSlot,
  testIdPrefix,
  panelClassName,
  triggerClassName,
}: TriggerShapeProps<K>) {
  const current = selectedControlOption(control);
  return (
    <Popover>
      <ToolbarButton
        aria-label={controlTriggerLabel(control)}
        title={control.label}
        data-control={control.id}
        data-kind={control.kind}
        data-trigger={control.trigger}
        data-mixed={current ? undefined : true}
        data-testid={testIdPrefix ? `${testIdPrefix}-control-${control.id}` : undefined}
        className={cn(
          "gap-1.5",
          // The Font size combobox (screenshot 03): a fixed-width row with
          // its own name left-aligned and the chevron pinned to the end,
          // matching FigJam's own 144px trigger (figjamTokens.ts's
          // `TEXT_TRIGGER_WIDTH`) rather than the icon triggers' snug fit.
          control.trigger === "text" && "w-36 justify-between px-2.5",
          // Last, so a host's traced cell wins over the kit's defaults.
          triggerClassName,
        )}
        render={<PopoverTrigger />}
      >
        <TriggerFace control={control} glyphs={glyphs} current={current} />
        <ChevronDown aria-hidden="true" className="size-3.5 shrink-0 opacity-70" />
      </ToolbarButton>
      <PopoverContent
        side="top"
        align="center"
        container={container}
        autoFocus={autoFocus}
        className={cn("w-auto", panelClassName)}
        // WHY no close-on-select handler: `closeOnSelect={false}` is
        // `ControlPanel`'s explicit documented default (MENU-KIT-DESIGN.md
        // §3.3 — "align-then-distribute is the normal two-step; staying
        // open is policy, not an accident of which library we wrapped").
        // Base UI's own `Popover` already stays open on an inner click with
        // zero extra wiring (it only closes on outside click, Escape, or
        // the trigger itself), so the policy is satisfied by NOT adding an
        // auto-close callback here — adding one would be the accident this
        // WHY warns against.
        onPointerDownCapture={onPanelPointerDownCapture}
      >
        <ControlPanel
          control={control}
          glyphs={glyphs}
          customColorSlot={customColorSlot}
          testIdPrefix={testIdPrefix}
        />
      </PopoverContent>
    </Popover>
  );
}

function TriggerFace<K extends string>({
  control,
  glyphs,
  current,
}: {
  control: BoundControl<K>;
  glyphs: GlyphFamilies;
  current: ReturnType<typeof selectedControlOption>;
}) {
  if (control.trigger === "text") {
    const customPx = readCustomPx(control);
    return (
      <>
        <span className="min-w-0 flex-1 truncate text-left text-sm">
          {customPx ?? current?.label ?? MIXED_LABEL}
        </span>
        {customPx === null ? (
          <RungPxReadout control={control} value={current?.value} />
        ) : null}
      </>
    );
  }
  if (isAutomaticSelection(control)) {
    return (
      <span aria-hidden="true" className="font-mono text-xs font-extrabold">
        A
      </span>
    );
  }
  return (
    <span
      aria-hidden="true"
      className={cn(
        "flex size-6 items-center justify-center",
        // WHY only `trigger==='value'` dims: a value-preview trigger with no
        // shared value must not show one option's crisp glyph as if it were
        // chosen (appearance.css's own WHY, carried verbatim) — a fixed-icon
        // trigger (`trigger==='icon'`) stays solid because its icon NAMES
        // the control, it never previews a value in the first place.
        control.trigger === "value" && !current && "opacity-40",
      )}
    >
      {/* `triggerGlyph` wins here and ONLY here — an option cell always draws
          with `glyph`, so a trigger can show something the options are not. */}
      {(() => {
        const family = control.triggerGlyph ?? control.glyph;
        if (!family) return null;
        return glyphs[family]?.(control.trigger === "value" ? current?.value : undefined);
      })()}
    </span>
  );
}

function readCustomPx<K extends string>(control: BoundControl<K>): string | null {
  const customSize = control.customSize;
  if (!customSize || customSize.onPresetRungs) return null;
  return typeof customSize.sharedPx === "number" ? `${formatPx(customSize.sharedPx)} px` : MIXED_LABEL;
}

function RungPxReadout<K extends string>({ control, value }: { control: BoundControl<K>; value?: string }) {
  const px = value !== undefined ? control.rungPxByValue?.[value] : undefined;
  if (px === undefined || px === null) return null;
  return (
    <span
      data-testid="control-trigger-rung-px"
      // The trigger's ink at 60%, not `text-muted-foreground` — the same rule
      // as `controlPanel.tsx`'s change 4, one level up: the trigger sits on
      // the host's skinned bar, and a page token on a fixed surface is right
      // in one colour scheme and wrong in the other. The donor mutes this
      // exact readout the same way (appearance.css:73, 55% of the pill ink).
      className="shrink-0 pr-0.5 text-xs text-current/60 tabular-nums"
    >
      {formatPx(px)}
    </span>
  );
}

/** Ours, ad hoc — the one-decimal rounding rule of the donor's
    `formatFontPx` (customFontSize.ts:231-234), which does not itself port
    (see change 6 above); only this small formatting rule travels. */
function formatPx(px: number): string {
  const rounded = Math.round(px * 10) / 10;
  return Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(1);
}

const TRIGGER_SHAPES: Record<ControlTrigger, TriggerShapeComponent> = {
  toggle: ToggleTrigger,
  action: ActionTrigger,
  value: PopoverTriggerShape,
  icon: PopoverTriggerShape,
  text: PopoverTriggerShape,
};

// src/editor/controlValue.ts — ported from SystemSketch, read-only
// donor at /home/bam/systemsketch, revision
// `10748b8ccdb374e71714f3d351abc43947ecfb0e`:
//
//   • `src/contextualMenus/sharedValues.ts:19-46` — `sharedValueAcross`
//     (renamed from nothing, kept) and `combineSharedStyles` (renamed here
//     to `combineControlValues` to match this file's own type name).
//
// WHAT CHANGED in the port: the donor's `SharedStyle<T>` is `import type {
// SharedStyle } from 'tldraw'` — the one load-bearing borrowed type this
// whole architecture otherwise has none of. The core imports no canvas
// engine, so that type is redefined here as `ControlValue<T>`, structurally
// identical (`{ type: 'shared'; value: T } | { type: 'mixed' }`), and every
// donor function is renamed to match (`sharedEdgeValue`-style call sites
// don't travel — only the two generic folds do). Nothing else changed: same
// three-state model (design decision #3 — mixed-state folding is the
// essence of multi-selection property editing, so the "shared | mixed"
// shape stays exactly as SystemSketch designed it), same default equality,
// same abstention rule.

/**
 * The result of asking "does this property agree across every subject bound
 * to a control?" — three states, never two: a control can KNOW one value, know
 * they DISAGREE, or have asked nobody at all (see `sharedValueAcross`'s
 * `undefined` return, which is not a member of this type on purpose).
 */
export type ControlValue<T> = { type: "shared"; value: T } | { type: "mixed" };

/**
 * THE one reduce for "do these agree?".
 *
 * WHY (ported verbatim, sharedValues.ts:6-17): every contextual surface
 * needs "is this property the same across every relevant subject, or
 * mixed" — and each surface used to hand-roll its own fold (`combineShared`
 * in appearanceModel, `sharedEdgeValue` in strokeMeta, a first+every in the
 * appearance pill's arrow reading, an epsilon-compare in customFontSize).
 * Divergent copies of the same fold are how one menu says mixed while its
 * neighbour claims a value. Surfaces fold raw readings with
 * `sharedValueAcross` and already-folded readings with
 * `combineControlValues`; neither is reimplemented at a call site.
 *
 * `undefined` readings mean "this subject has nothing to say" and are
 * skipped rather than counted as disagreement; a set with no opinions folds
 * to `undefined`, never to a fabricated value.
 */
export function sharedValueAcross<T>(
  values: Iterable<T | undefined>,
  equals: (a: T, b: T) => boolean = Object.is,
): ControlValue<T> | undefined {
  let found: T | undefined;
  let has = false;
  for (const value of values) {
    if (value === undefined) continue;
    if (!has) {
      found = value;
      has = true;
    } else if (!equals(found as T, value)) {
      return { type: "mixed" };
    }
  }
  return has ? { type: "shared", value: found as T } : undefined;
}

/** Fold readings that are already shared/mixed verdicts into one verdict. */
export function combineControlValues<T>(
  readings: readonly (ControlValue<T> | undefined)[],
  equals?: (a: T, b: T) => boolean,
): ControlValue<T> | undefined {
  const present = readings.filter((reading): reading is ControlValue<T> => reading !== undefined);
  if (present.some((reading) => reading.type === "mixed")) return { type: "mixed" };
  return sharedValueAcross(
    present.map((reading) => (reading as { type: "shared"; value: T }).value),
    equals,
  );
}

// src/editor/toolbar.tsx — shadcn has no toolbar item in any style
// (verified 404 twice against the shadcn/ui and base-nova registries), so
// this is a new wrapper, not a copy — over Base UI's `@base-ui/react/toolbar`
// (`Toolbar.Root/Group/Button/Separator/Link`, verified against the real
// package: apps/storybook-basics/node_modules/@base-ui/react/toolbar/
// index.parts.d.ts), styled in the same shadcn/Tailwind idiom as every other
// L1 part here (`cn` + shadcn CSS variables, no raw `style={{color}}`).
"use client";

import { Toolbar as ToolbarPrimitive } from "@base-ui/react/toolbar";

import { cn } from "../lib/utils";
import { BAR_SIZE_TO_BUTTON_SIZE, useBarSize, type ButtonToggleSize } from "../components/barSize";

/**
 * `Toolbar` is the roving-focus container underneath the floating pill
 * (screenshot 01), the bottom tool dock (04), the top-left chrome bar (05)
 * and the status strip — every one of those surfaces is "a row of buttons
 * where arrow keys move focus and only one stop is ever tab-reachable",
 * which is exactly Base UI's `Toolbar.Root` contract (roving tabindex +
 * arrow-key navigation + `loopFocus`) rather than a plain flex row of
 * `Button`s. Anything that composes a `Bar` with tool buttons in one of its
 * slots wants a `Toolbar` in that slot, not raw buttons.
 *
 * WHY it also publishes size via `useBarSize` (barSize.tsx), exactly like
 * `button.tsx`: a toolbar's buttons should size themselves off the ambient
 * Bar the toolbar sits inside (Zach's size-cascade ask, see bar.tsx) without
 * every call site re-passing `size` to every `ToolbarButton`. `size` here is
 * read-only plumbing for the caller's OWN buttons (see `ToolbarButton`
 * below) — the cascade travels through context already mounted by `Bar`,
 * this component does not re-provide it.
 */
function Toolbar({ className, ...props }: ToolbarPrimitive.Root.Props) {
  return (
    <ToolbarPrimitive.Root
      data-slot="toolbar"
      className={cn(
        "flex items-center gap-1 outline-none data-[orientation=vertical]:flex-col data-[orientation=vertical]:items-stretch",
        className,
      )}
      {...props}
    />
  );
}

function ToolbarGroup({ className, ...props }: ToolbarPrimitive.Group.Props) {
  return (
    <ToolbarPrimitive.Group
      data-slot="toolbar-group"
      className={cn("flex items-center gap-1", className)}
      {...props}
    />
  );
}

/**
 * Renders a `<button>` by default, styled to match `button.tsx`'s own
 * `ghost` "icon" look (toolbar buttons are near-always icon-only — the
 * fill/hatched/transparent cells in screenshot 01, the cursor/frame/shape
 * tools in 04). A consumer that wants the FULL `Button` (variants, the
 * `Bar` size cascade already resolved, `render`-based composition with a
 * `DropdownMenuTrigger`, etc.) passes `render={<Button .../>}` — same seam
 * `DropdownMenuTrigger`/`TooltipTrigger` already use — rather than this
 * component growing a second copy of `buttonVariants`.
 *
 * `size` is accepted only to resolve the ambient Bar cascade for THIS
 * button's own touch target (`h-7`/`h-8`/`h-9`) when the caller renders the
 * plain built-in button rather than composing `Button`; it is stripped
 * before reaching the DOM node.
 */
function ToolbarButton({
  className,
  size,
  ...props
}: ToolbarPrimitive.Button.Props & { size?: ButtonToggleSize }) {
  const barSize = useBarSize();
  const resolvedSize = size ?? (barSize && BAR_SIZE_TO_BUTTON_SIZE[barSize]) ?? "default";
  return (
    <ToolbarPrimitive.Button
      data-slot="toolbar-button"
      data-size={resolvedSize}
      className={cn(
        // WHY `aria-pressed:` rather than a `data-pressed` attribute: Base
        // UI's `Toolbar.Button` has no built-in pressed state of its own
        // (that's `toggle.tsx`'s job, and a toolbar tool button IS just an
        // `aria-pressed` button — screenshot 04's blue cursor tool) — the
        // consumer sets `aria-pressed` and the style follows for free,
        // matching `toggle.tsx`'s own `aria-pressed:bg-muted` convention.
        "inline-flex shrink-0 items-center justify-center gap-1.5 rounded-lg text-sm font-medium whitespace-nowrap outline-none transition-all select-none hover:bg-muted hover:text-foreground focus-visible:ring-3 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 aria-pressed:bg-primary aria-pressed:text-primary-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        resolvedSize === "sm" && "h-7 px-2",
        resolvedSize === "default" && "h-8 px-2.5",
        resolvedSize === "lg" && "h-9 px-2.5",
        className,
      )}
      {...props}
    />
  );
}

function ToolbarLink({ className, ...props }: ToolbarPrimitive.Link.Props) {
  return (
    <ToolbarPrimitive.Link
      data-slot="toolbar-link"
      className={cn(
        "text-primary text-sm underline-offset-4 outline-none hover:underline focus-visible:ring-3 focus-visible:ring-ring/50",
        className,
      )}
      {...props}
    />
  );
}

/**
 * WHY a plain `bg-border` bar rather than reusing `separator.tsx`'s
 * `Separator`: Base UI's own `Toolbar.Separator` (this wraps it) already
 * carries the toolbar-specific default — vertical in a horizontal toolbar,
 * horizontal in a vertical one — and participates in the roving-focus
 * DOM structure the plain `Separator` primitive doesn't know about.
 * Screenshot 04's dock draws exactly this: a hairline between the tool
 * group and the trailing `+`.
 */
function ToolbarSeparator({ className, ...props }: ToolbarPrimitive.Separator.Props) {
  return (
    <ToolbarPrimitive.Separator
      data-slot="toolbar-separator"
      className={cn(
        "bg-border shrink-0 self-stretch data-[orientation=vertical]:mx-1 data-[orientation=vertical]:w-px data-[orientation=horizontal]:my-1 data-[orientation=horizontal]:h-px",
        className,
      )}
      {...props}
    />
  );
}

export { Toolbar, ToolbarButton, ToolbarGroup, ToolbarLink, ToolbarSeparator };

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
